INSERT INTO `our_services_why_items` VALUES (1,0,'images/service-page-icon-1.svg','Experienced, Full-Time Financial Aid Professionals','Our team consists of 100-200 full-time W2 employees, providing consistent and reliable service.',1,'2026-09-24 10:11:52','2026-09-24 10:11:52'),(2,1,'images/service-page-icon-3.svg','Fast & Efficient Processing','We offer industry-leading turnaround times with direct supportΓÇöno frustrating ticket queues.',1,'2026-09-24 10:11:52','2026-09-24 10:11:52'),(3,2,'images/service-page-icon-2.svg','Comprehensive Support','Whether itΓÇÖs staffing, processing, compliance, or student outreach, we help schools navigate complex challenges.',1,'2026-09-24 10:11:52','2026-09-24 10:11:52'),(4,3,'images/service-page-icon-4.svg','Live, Real-Time Assistance','Unlike competitors, we offer instant support via phone, email, chat, and video conferencing.',1,'2026-09-24 10:11:52','2026-09-24 10:11:52');
