INSERT INTO `page_sections` VALUES (1,1,'hero','{\"title\":\"New Financial Aid Regs Are Here (OB3)\",\"subtitle\":\"Are You Prepared? Are You Really?\",\"paragraph_1\":\"Staffing shortages, burnout, and processing backlogs are delaying responses to student calls and emails, leaving financial aid teams overwhelmed and students frustrated.\",\"paragraph_2\":\"FA Solutions provides experienced financial aid professionals and scalable shared or outsourced solutions to support financial aid processing operations and student communication.\",\"button_text\":\"Get Started\",\"button_route\":\"get-started\",\"image_1\":\"images\\/FA+Solution-800h.webp\",\"image_1_alt\":\"Students collaborating in a library\",\"image_2\":\"images\\/FA+Solutions+FAFSA+(1)-1000h.webp\",\"image_2_alt\":\"Students receiving financial aid support\"}',0,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(2,1,'intro','{\"title\":\"Real People. Real Expertise.SIMULATED\",\"paragraph_1\":\"FA Solutions partners with colleges as an extension to their team to strengthen financial aid operations and navigate compliance with confidence. Powered by experienced, full-time higher education financial aid professionals, we deliver consistent, reliable results institutions and students can depend on.\",\"paragraph_2\":null,\"paragraph_3\":null,\"button_text\":\"Meet Our Team\",\"button_route\":\"team\",\"image\":null}',1,1,'2026-09-20 10:26:24','2026-09-22 01:51:56'),(3,1,'difference','{\"title\":\"Our Difference:\",\"form_title\":\"Get in Touch\",\"items\":[{\"icon\":\"images\\/difference-icon-1.png\",\"title\":\"Full-Time W2 Team\",\"content\":\"Unlike many competitors, we rely on full-time experts, not just consultants.\"},{\"icon\":\"images\\/difference-icon-2.png\",\"title\":\"Decades of Experience\",\"content\":\"Our leadership team has been in higher ed financial aid for over 25 years.\"},{\"icon\":\"images\\/difference-icon-3.png\",\"title\":\"Custom Solutions, No One-Size-Fits-All Approach\",\"content\":\"Tailored services based on each school\'s needs.\"}]}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(4,1,'why','{\"title\":\"Why FA Solutions?\",\"button_text\":\"Get Started\",\"button_route\":\"get-started\",\"items\":[{\"title\":\"We\'re an Extension of Your Team\",\"content\":\"We don\'t just offer services; we integrate with your operations.\"},{\"title\":\"No Forced Platform Changes\",\"content\":\"We work with your existing financial aid software.\"},{\"title\":\"Real Customer Service, Not Automated Responses\",\"content\":\"Immediate access to real experts.\"}]}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(5,1,'services','{\"title\":\"Our Services\",\"cards\":[{\"image\":\"images\\/Financial+Aid+Processing+FA+Solutions+(1)-1920w.webp\",\"image_alt\":\"Financial Aid Processing and Compliance\",\"title\":\"1. Financial Aid Processing & Compliance\",\"intro\":\"Slow, unresponsive third-party services are frustrating. We offer seamless financial aid processing:\",\"bullets\":\"Works with Most Major Student Systems \\u2013 No need to change platforms.\\nLive Customer Support \\u2013 Real-time assistance all day during working hours.\\nFull Compliance Oversight \\u2013 We ensure audits and program reviews don\'t become major issues.\",\"button_text\":\"Learn More About Processing\",\"button_route\":\"financial-aid-processing\"},{\"image\":\"images\\/2.+Financial+Aid+Staffing-1920w.webp\",\"image_alt\":\"Financial Aid Staffing\",\"title\":\"2. Financial Aid Staffing\",\"intro\":\"Staffing shortages are costly and disruptive. Our staffing solutions have doubled client revenue from $30K to $60-70K annually:\",\"bullets\":\"Long-Term, Dependable Staff \\u2013 No short-term fixes.\\nBuilt-in Redundancy \\u2013 2-3 professionals per role.\\nFlexible Support Models \\u2013 Remote, hybrid, or on-site.\",\"button_text\":\"Explore Staffing Solutions\",\"button_route\":\"financial-aid-staffing\"},{\"image\":\"images\\/3.+Student+Outreach+-+Communication-1920w.webp\",\"image_alt\":\"Student Outreach and Communication\",\"title\":\"3. Student Outreach & Communication\",\"intro\":\"Colleges struggle with effective student communication. We offer a full-service contact center for:\",\"bullets\":\"Inbound & Outbound Support \\u2013 Phone, email, and mass text messaging.\\nAI-Powered Two-Way Texting \\u2013 Real-time messaging.\\nCustom Outreach Programs \\u2013 Mass messages for deadlines.\",\"button_text\":\"Improve Student Communication\",\"button_route\":\"student-outreach-communication\"},{\"image\":\"images\\/FA+Solutions+FAFSA+(1)-1000h.webp\",\"image_alt\":\"Financial Aid Consulting and Operational Strategy\",\"title\":\"4. Financial Aid Consulting & Operational Strategy\",\"intro\":\"Many schools don\'t know they have compliance risks until it\'s too late. Our consulting services include:\",\"bullets\":\"Regulatory & Operational Assessments \\u2013 Prevent costly audit findings.\\nTitle IV Approval & Accreditation Support \\u2013 Expert guidance.\\nHCM1 & HCM2 Support \\u2013 Helping schools regain financial stability.\",\"button_text\":\"Get Expert Compliance Support\",\"button_route\":\"financial-aid-consulting\"}]}',4,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(6,1,'success','{\"title\":\"Client Success Stories\",\"subtitle\":\"How We\'ve Helped Schools Like Yours\",\"items\":[{\"content\":\"Large University \\u2013 Doubled efficiency while reducing financial aid staff turnover.\"},{\"content\":\"Mid-Sized College \\u2013 Improved student engagement by 30% through proactive outreach.\"},{\"content\":\"Small Private School \\u2013 Cleared financial aid application backlog in under 60 days.\"}],\"button_text\":\"Read More Case Studies\",\"button_route\":\"case-studies\"}',5,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(7,1,'image_gallery','{\"image_1\":\"images\\/c-success-1.jpg\",\"image_1_alt\":\"Students collaborating in a campus setting\",\"image_2\":\"images\\/c-success-2.jpg\",\"image_2_alt\":\"Students working together on financial aid\"}',6,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(8,1,'faq','{\"title\":\"Frequently Asked Questions\",\"image\":\"images\\/faq.webp\",\"image_alt\":\"Students at graduation ceremony\",\"button_text\":\"View All FAQs\",\"button_route\":\"faq\",\"items\":[{\"question\":\"How do I sign up for services through FA Solutions?\",\"answer\":\"Getting started is simple. We begin with a quick consultation to learn more about your needs and goals, and to make sure we\'re the right fit for your organization.\"},{\"question\":\"What does pricing look like?\",\"answer\":\"Our pricing depends on multiple factors, including institution size, pain points, experience levels needed, and systems used.\"},{\"question\":\"How do you mitigate risk for schools?\",\"answer\":\"We help reduce the risk of audit findings, compliance violations, and financial instability by offering tailored solutions that ensure institutions meet regulatory requirements.\"}]}',7,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(9,3,'banner','{\"label\":\"About Us\",\"title\":\"Who We Are\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(10,3,'about_partner','{\"title\":\"Your Financial Aid Partner\",\"paragraph_1\":\"FA Solutions isn\'t just another financial aid servicer\\u2014we\'re a true partner to the institutions we work with. We integrate seamlessly with schools to enhance efficiency, ensure compliance, and deliver exceptional financial aid experiences. Our team is not only highly experienced but also deeply committed to the success of both institutions and their students.\",\"paragraph_2\":\"With a leadership team boasting 25+ years of financial aid experience and a staff of 100-200 full-time W2 financial aid professionals, we have the expertise and scale to support schools of all sizes. Unlike other providers that rely heavily on independent consultants, our full-time team ensures reliability, consistency, and deep institutional knowledge.\",\"button_text\":\"Get Started\",\"button_route\":\"get-started\",\"image\":\"images\\/about-1.webp\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(11,3,'about_believe','{\"title\":\"What We Believe\",\"paragraph_1\":\"Choosing a financial aid partner is a critical decision. Just as schools must carefully evaluate their vendors, we ensure that our partnerships are a strong cultural and operational fit.\",\"paragraph_2\":\"We\'ve partnered with nearly 100 institutions over the past decade, offering industry-leading processing turnaround times and hands-on expertise in all major financial aid systems, including Anthology, Colleague, Banner, PowerFAIDS, Regent, and Campus Caf\\u00e9.\",\"paragraph_3\":\"At FA Solutions, we understand that financial aid is about more than just compliance\\u2014it\'s about ensuring students get the support they need. Our services help institutions streamline operations, reduce administrative burden, and enhance student experiences.\",\"button_text\":\"Learn More About Our Approach\",\"button_route\":\"get-started\",\"image\":\"images\\/about-2-new.jpg\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(12,3,'clients','{\"title\":\"Partial List Of Our Clients\",\"paragraph_1\":\"We are proud to work with amazing clients that have provided raving reviews for our services.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(13,3,'faq','{\"title\":\"Frequently Asked Questions\",\"image\":\"images\\/about-faq.png\",\"items\":[{\"question\":\"How do I sign up for services through FA Solutions?\",\"answer\":\"We begin with a quick consultation to learn more about your needs and goals, and to make sure we\'re the right fit for your organization. From there, we\'ll walk you through the next steps and recommend the best solution for you.\"},{\"question\":\"What does pricing look like?\",\"answer\":\"Pricing varies based on:Institution size and type\\nExisting financial aid system\\nLevel of expertise required\\nComplexity of the institution\'s pain pointsWe are a premium service\\u2014not a discount provider\\u2014because compliance, efficiency, and student success are too important to compromise.\"},{\"question\":\"Do you offer on-site or remote support?\",\"answer\":\"Yes! We offer both on-site and fully remote financial aid support, depending on your institution\'s needs and preferences.\"},{\"question\":\"What levels of financial aid staffing do you provide?\",\"answer\":\"We provide long-term staffing solutions for financial aid offices, ensuring redundancy and eliminating turnover disruptions. Our staffing solutions include financial aid directors, processors, advisors, and verification specialists.\"},{\"question\":\"Can you conduct compliance audits?\",\"answer\":\"Absolutely. We provide regulatory compliance audits, Title IV consulting, and operational assessments to prevent audit findings and mitigate risk.\"}]}',4,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(14,4,'banner','{\"label\":\"Meet Our\",\"title\":\"Leadership Team\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(15,4,'team','{\"title\":\"Meet Our Leadership Team\",\"members\":[{\"name\":\"Brenda Wright\",\"title\":\"Executive Chief Operating Officer\",\"image\":\"images\\/brenda-wright.webp\",\"slug\":\"brenda-wright\"},{\"name\":\"Rob Wright\",\"title\":\"Co-Founder and Managing Member\",\"image\":\"images\\/rob-wright.webp\",\"slug\":\"rob-wright\"},{\"name\":\"Kim Dean\",\"title\":\"Chief Financial Officer\",\"image\":\"images\\/kim-din.webp\",\"slug\":\"kim-dean\"},{\"name\":\"Bridget McGuire\",\"title\":\"Chief Operating Officer\",\"image\":\"images\\/Bridget McGuire.webp\",\"slug\":\"bridget-mcguire\"},{\"name\":\"Tiffany Badgero\",\"title\":\"Vice President of People & Business Operations\",\"image\":\"images\\/Tiffany Badgero.webp\",\"slug\":\"tiffany-badgero\"},{\"name\":\"Michael Holmes\",\"title\":\"Vice President of Technology & Compliance\",\"image\":\"images\\/michle.webp\",\"slug\":\"michael-holmes\"},{\"name\":\"Melanie Lindenmeyer\",\"title\":\"Vice President Regulatory Compliance, Audit & Training\",\"image\":\"images\\/Melanie Lindenmeyer.webp\",\"slug\":\"melanie-lindenmeyer\"},{\"name\":\"Julie Anderson\",\"title\":\"Director of FA Operations\",\"image\":\"images\\/julie.webp\",\"slug\":\"julie-anderson\"},{\"name\":\"Erin Baxley\",\"title\":\"Director of FA Operations\",\"image\":\"images\\/erin.webp\",\"slug\":\"erin-baxley\"},{\"name\":\"Tammy Bentze\",\"title\":\"Director of FA Operations\",\"image\":\"images\\/tammy.webp\",\"slug\":\"tammy-bentze\"},{\"name\":\"Michael Dozier\",\"title\":\"Director of FA Operations\",\"image\":\"images\\/Michael Dozier.webp\",\"slug\":\"michael-dozier\"},{\"name\":\"Katie Norris\",\"title\":\"Director of Growth & Partnerships\",\"image\":\"images\\/katie.webp\",\"slug\":\"katie-norris\"},{\"name\":\"Amy Norton\",\"title\":\"Director of Business Information Systems\",\"image\":\"images\\/amy.webp\",\"slug\":\"amy-norton\"},{\"name\":\"Heather Taynor\",\"title\":\"Strategic Client & Growth Advisor\",\"image\":\"images\\/Heather Taynor.webp\",\"slug\":\"heather-taynor\"},{\"name\":\"Nydia Willard\",\"title\":\"Director of Student Experience\",\"image\":\"images\\/nydia.webp\",\"slug\":\"nydia-willard\"}]}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(16,5,'banner','{\"label\":\"Our\",\"title\":\"Trusted Partners\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(17,5,'partner_logos','{\"logos\":[{\"image\":\"images\\/insync.png\",\"alt\":\"insync\"},{\"image\":\"images\\/mac-insight.png\",\"alt\":\"MAC Insight Group\"},{\"image\":\"images\\/source.png\",\"alt\":\"Source for Training\"}]}',1,1,'2026-09-20 10:26:24','2026-09-20 11:10:57'),(18,5,'partner_impact','{\"title\":\"Partnerships That Extend Our Impact\",\"paragraph_1\":\"At FA Solutions LLC, we collaborate with organizations that bring specialized expertise across the higher education landscape. These partnerships allow us to enhance our capabilities and provide institutions with more comprehensive, integrated support.\",\"paragraph_2\":\"By working alongside trusted partners in enrollment strategy, technology, and training, we help institutions navigate operational complexity while improving efficiency, compliance, and student outcomes.\",\"card_image\":\"images\\/partner-bg.jpg\",\"card_link_route\":\"get-started\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:10:57'),(19,5,'partner_commitment','{\"title\":\"Our Commitment:\",\"items\":[{\"title\":\"Real People, Real Expertise\",\"description\":\"We work as an extension of your financial aid office, offering long-term, sustainable solutions.\"},{\"title\":\"Customized Support\",\"description\":\"No one-size-fits-all approach; we tailor our services based on each institution\'s needs.\"},{\"title\":\"Operational Efficiency & Compliance\",\"description\":\"We help schools navigate financial aid challenges while mitigating risk and maintaining regulatory compliance.\"}],\"button_text\":\"Schedule a Consultation to Learn More\",\"button_route\":\"get-started\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:10:57'),(20,12,'banner','{\"label\":\"Get Started With\",\"title\":\"FA Solutions\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(21,12,'started','{\"title\":\"Stronger Financial Aid Support Starts Here\",\"paragraph_1\":\"Processing delays, staffing gaps, compliance demands, and unanswered student questions can\\r\\n                            quickly affect enrollment, retention, and trust. FA Solutions provides experienced financial\\r\\n                            aid professionals and scalable and flexible operational support to help your team stay\\r\\n                            responsive, compliant, and ready for what\'s next.\",\"newsletter_label\":\"Subscribe to our Newsletters\",\"button_1_text\":\"Join Our Webinars\",\"button_1_route\":\"webinar\",\"button_1_url\":null,\"button_2_text\":\"See How We Can Help\",\"button_2_route\":null,\"button_2_url\":\"http:\\/\\/dev.getfasolutions.digiperfecto.com\\/get-started\",\"contact_form_title\":\"Get in Touch\",\"recaptcha_notice\":\"This site is protected by reCAPTCHA. Google\'s Privacy Policy and Terms of Service apply.\"}',1,1,'2026-09-20 10:26:24','2026-09-23 11:23:42'),(22,12,'started_follow','{\"title\":\"Follow us\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(23,12,'killers','{\"title\":\"The Silent Killers of Student Enrollment.\",\"button_text\":\"Get Reliable Financial Aid Support\",\"paragraph_1\":\"Processing delays aren\\u2019t just paperwork\\u2014they\\u2019re lost students.\",\"paragraph_2\":\"Compliance isn\\u2019t a \\u201ccheck-the-box\\u201d task; it\\u2019s the foundation of your Title IV eligibility.\",\"paragraph_3\":\"Staffing shortages lead to \\u201cinstitutional memory\\u201d loss. We provide the redundancy you lack.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(24,7,'banner','{\"label\":\"Our Services\",\"title\":\"Financial Aid Processing & Compliance\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(25,7,'intro','{\"button_text\":\"Get Reliable Financial Aid Support\",\"paragraph_1\":\"Managing financial aid processing is a critical yet complex task for institutions. Delays,\\n                            compliance risks, and inefficient systems can negatively impact student enrollment and\\n                            retention. At FA Solutions, we specialize in providing fast, accurate, and fully compliant\\n                            financial aid processing tailored to your institution\\u2019s needs. Our experienced team ensures\\n                            your operations run smoothly while meeting all federal and Title IV regulations.\",\"paragraph_2\":\"With our dedicated support, you won\\u2019t have to worry about slow processing times or\\n                            compliance pitfalls. We work with most major student systems, provide real-time customer\\n                            support, and proactively manage regulatory requirements. Let us help you streamline\\n                            financial aid operations, reduce risk, and enhance the student experience.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(26,7,'simplify','{\"title\":\"How We Simplify Financial Aid Processing\",\"button_text\":\"Get Reliable Financial Aid Support\",\"paragraph_1\":\"We support major systems like Anthology, Colleague, Banner, PowerFAIDS, Regent, and\\n                                Campus Caf\\u00e9, ensuring a smooth, unchanged transition.\",\"paragraph_2\":\"Our live customer support team is available throughout the day, eliminating frustrating\\n                                ticketing queues and long wait times.\",\"paragraph_3\":\"Compliance is our priority. We help institutions meet Title IV and federal financial aid\\n                                regulations, reducing audit risks and ensuring smooth operations.\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(27,7,'cases','{\"title\":\"How We Helped Institutions Like Yours\",\"paragraph_1\":\"Luther Rice College & Seminary faced similar challenges as Faith International\\n                            University, coming from a third-party servicer with outdated technology and slow processing\\n                            times.\",\"paragraph_2\":\"Concordia University faced challenges due to rapid growth. It struggled to keep up with\\n                            financial aid packaging, document verification, and timely communication with students.\",\"paragraph_3\":\"Faith International University previously worked with a third-party servicer for financial\\n                            aid processing but faced issues with outdated technology, delayed aid packaging, and slow\\n                            customer service response times, leading to delays in receiving federal financial aid.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(28,8,'banner','{\"label\":\"Our Services\",\"title\":\"Financial Aid Staffing\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(29,8,'intro','{\"button_text\":\"Find Your Staffing Solution\",\"paragraph_1\":\"Staffing shortages can lead to processing delays, compliance risks, and lost revenue for\\n                            institutions. At FA Solutions, we provide experienced financial aid professionals who\\n                            seamlessly integrate into your team\\u2014whether remote, hybrid, or on-site. Our staffing\\n                            solutions ensure your institution remains efficient, compliant, and fully supported, helping\\n                            you avoid disruptions and maintain student satisfaction.\",\"paragraph_2\":\"Unlike short-term fixes, we offer long-term, dependable staffing solutions with built-in\\n                            redundancy. Each role is supported by 2-3 professionals, ensuring uninterrupted service. Our\\n                            clients have seen revenue growth from $30K to $60-70K annually through improved operational\\n                            efficiency. Let us help you build a stronger, more reliable financial aid team.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(30,8,'why','{\"title\":\"Why Institutions Trust Our Staffing Solutions\",\"button_text\":\"Find Your Staffing Solution\",\"paragraph_1\":\"We provide highly skilled financial aid experts who offer long-term support, not\\n                                temporary solutions.\",\"paragraph_2\":\"Each role is backed by multiple professionals, ensuring coverage during staff transitions\\n                                or high-demand periods.\",\"paragraph_3\":\"Whether your institution operates remotely, in-person, or hybrid, our staff easily adapt\\n                                to your processes and culture.\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(31,8,'cases','{\"title\":\"How We Helped Institutions Like Yours\",\"paragraph_1\":\"Luther Rice College & Seminary faced similar challenges as Faith International\\n                            University, coming from a third-party servicer with outdated technology and slow processing\\n                            times.\",\"paragraph_2\":\"Concordia University faced challenges due to rapid growth. It struggled to keep up with\\n                            financial aid packaging, document verification, and timely communication with students.\",\"paragraph_3\":\"Faith International University previously worked with a third-party servicer for financial\\n                            aid processing but faced issues with outdated technology, delayed aid packaging, and slow\\n                            customer service response times, leading to delays in receiving federal financial aid.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(32,9,'banner','{\"label\":\"Our Services\",\"title\":\"Student Outreach & Communication\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(33,9,'intro','{\"button_text\":\"Improve Student Communication\",\"paragraph_1\":\"Effective communication is key to student engagement and financial aid success, yet many\\n                            institutions struggle with reaching students in a timely and efficient manner. FA Solutions\\n                            provides a full-service contact center designed to streamline student outreach through\\n                            phone, email, and text messaging. Our team ensures that students receive the information\\n                            they need\\u2014when and how they prefer\\u2014reducing missed deadlines and incomplete applications.\",\"paragraph_2\":\"With AI-powered two-way texting and custom outreach programs, we help institutions\\n                            proactively connect with students. Whether it\'s responding to inquiries, sending deadline\\n                            reminders, or assisting with financial aid documentation, our solutions improve engagement\\n                            and drive better enrollment outcomes.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(34,9,'simplify','{\"title\":\"How We Improve Student Engagement\",\"button_text\":\"Improve Student Communication\",\"paragraph_1\":\"We provide inbound and outbound assistance via phone, email, and mass text messaging,\\n                                ensuring students stay informed.\",\"paragraph_2\":\"Students prefer texting over calls. Our AI-driven system enables instant, two-way\\n                                communication.\",\"paragraph_3\":\"Schools can personalize messaging to notify students about missing documents, upcoming\\n                                deadlines, and financial aid updates.\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(35,9,'cases','{\"title\":\"Transforming Student Communication\",\"paragraph_1\":\"New Mexico State University required outbound communication support to assist students\\n                            through the admissions process during peak periods.\",\"paragraph_2\":\"Howard University initially worked with another call center company, which lacked experienced\\n                            financial aid professionals. This resulted in approximately 500 daily escalations back to\\n                            the school and a transactional billing method that led to inefficiencies.\",\"paragraph_3\":\"Horry Georgetown Technical College, estimated to have started working with FA Solutions in\\n                            2017, faced challenges with their third-party call center for financial aid inquiries.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(36,10,'banner','{\"label\":\"Our Services\",\"title\":\"Financial Aid Consulting & Operational Strategy\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(37,10,'intro','{\"button_text\":\"Get Expert Compliance Support\",\"paragraph_1\":\"Staying compliant with financial aid regulations is critical, yet many institutions don\\u2019t\\n                            identify risks until it\\u2019s too late. At FA Solutions, we provide expert consulting services\\n                            to help schools navigate complex regulatory requirements, improve operational efficiency,\\n                            and mitigate compliance risks before they become costly issues. Our tailored approach\\n                            ensures your institution remains aligned with industry best practices while maintaining\\n                            financial stability.\",\"paragraph_2\":\"From Title IV approval to accreditation consulting and heightened cash monitoring (HCM1 &\\n                            HCM2) support, we specialize in guiding institutions through challenging compliance\\n                            landscapes. Whether you\'re looking to streamline operations or regain financial health, our\\n                            team of higher education experts is here to help.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(38,10,'simplify','{\"title\":\"Our Compliance & Consulting Expertise\",\"button_text\":\"Get Expert Compliance Support\",\"paragraph_1\":\"We evaluate and optimize your financial aid processes to align with best practices and\\n                                regulatory requirements.\",\"paragraph_2\":\"Our experts guide institutions through Title IV approval and accreditation, ensuring a\\n                                smooth and compliant process.\",\"paragraph_3\":\"Unlike many providers, we specialize in helping schools under heightened cash monitoring\\n                                regain financial stability.\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(39,10,'cases','{\"title\":\"Strengthening Compliance & Operations\",\"paragraph_1\":\"Howard University initially worked with another call center company, which lacked experienced\\n                            financial aid professionals. This resulted in approximately 500 daily escalations back to\\n                            the school and a transactional billing method that led to inefficiencies.\",\"paragraph_2\":\"Luther Rice College & Seminary faced similar challenges as Faith International\\n                            University, coming from a third-party servicer with outdated technology and slow processing\\n                            times.\",\"paragraph_3\":\"Faith International University previously worked with a third-party servicer for financial\\n                            aid processing but faced issues with outdated technology, delayed aid packaging, and slow\\n                            customer service response times, leading to delays in receiving federal financial aid.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(40,13,'banner','{\"label\":\"FA Solutions\",\"title\":\"Our Testimonials\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(41,13,'testimonials','{\"title\":\"How We\'ve Helped\",\"paragraph_1\":\"\\u201cFA Solutions provided Schenectady County Community College\\n                            with outstanding expertise and resources to navigate us through a heightened period of\\n                            activity during a period when we were challenged with staffing issues in our Financial Aid\\n                            Office. Customer support is FA Solutions specialty! Our institutional call for support from\\n                            FA Solutions was answered quickly. FA Solutions partnered with our campus to provide\\n                            high-quality service to our student body during this peak period. Thank you, FA\\n                            Solutions.\\u201d\",\"paragraph_2\":\"Martha J. Asselin, Ph.D., Vice President of Student Affairs,\\n                            Schenectady County Community College\",\"paragraph_3\":\"\\u201cThe Technical College of the Lowcountry (TCL) is extremely\\n                            pleased with our partnership with FA Solutions. FA Solutions has provided us with excellent\\n                            service and quality outcomes. They are client-driven and have worked to find the best\\n                            solutions for us.\\u201d\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(42,13,'silent_killers','{\"title\":\"The Silent Killers of Student Enrollment.\",\"paragraph_1\":\"Processing delays aren\'t just paperwork\\u2014they\'re lost students.\",\"paragraph_2\":\"Compliance isn\'t a \\u201ccheck-the-box\\u201d task; it\'s the foundation of your Title IV eligibility.\",\"paragraph_3\":\"Staffing shortages lead to \\u201cinstitutional memory\\u201d loss. We provide the redundancy you lack.\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(43,14,'banner','{\"label\":\"Case Studies\",\"title\":\"Solving Challenges, Driving Results\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(44,14,'main','{\"title\":\"New Mexico State University\",\"paragraph_1\":\"New Mexico State University required outbound communication support to assist students through\\n                            the admissions process during peak periods.\",\"paragraph_2\":\"Howard University initially worked with another call center company, which lacked experienced\\n                            financial aid professionals. This resulted in approximately 500 daily escalations back to\\n                            the school and a transactional billing method that led to inefficiencies.\",\"paragraph_3\":\"Luther Rice College & Seminary faced similar challenges as Faith International\\n                            University, coming from a third-party servicer with outdated technology and slow processing\\n                            times.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(45,15,'banner','{\"label\":\"Resources\",\"title\":\"Our Blogs\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(46,15,'main','{\"title\":\"Essential Insights from Our OB3 Webinar\\n                                Series: Readiness, Policy Changes, and Workforce Pell\",\"paragraph_1\":\"July 2, 2026\",\"paragraph_2\":\"To help institutions move from awareness to readiness, FA Solutions hosted a full OB3 webinar\\n                            series, bringing our own experts together with industry leaders to break down exactly what\'s\\n                            changing and what to do about it.\",\"paragraph_3\":\"July 15, 2025\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(47,16,'banner','{\"label\":\"Resources\",\"title\":\"Fed-Updates\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(48,16,'main','{\"title\":\"Fed-Updates Financial Aid Newsletter September\\n                                2026\",\"paragraph_1\":\"September 8, 2026\",\"paragraph_2\":\"Fed-Updates Financial Aid Newsletter \\u2013 September 2026\",\"paragraph_3\":\"August 6, 2026\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(49,17,'banner','{\"label\":\"FAFSA Simplification\",\"title\":\"Knowledge Nuggets\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(50,17,'main','{\"title\":\"Preparing for FAFSA Simplification\",\"button_text\":\"Learn More\",\"paragraph_1\":\"Embracing the Future: Best Practices in Change Management for FAFSA Simplification\",\"paragraph_2\":\"A practical look at how institutions can prepare people,\\n                                processes, and systems for FAFSA simplification.\",\"paragraph_3\":\"FAFSA simplification is not a simple tech change but a comprehensive, broad updating that\\u2019s\\n                            both necessary and complex. Find out how colleges and universities can improve outcomes by\\n                            getting some help throughout this transition.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:42'),(51,18,'banner','{\"label\":\"Resources\",\"title\":\"White Paper Reports\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(52,18,'main','{\"title\":\"An Overview of the Recent Changes to the Higher Education Opportunity Act and Their Impact\\n                            on Financial Aid\",\"button_text\":\"View Full\\n                            Report\",\"paragraph_1\":\"An overview of the recent changes to the Higher Education Opportunity Act and their\\n                                impact on financial aid.\",\"paragraph_2\":\"The Higher Education Opportunity Act went into place in 2008 and made substantial changes to\\n                            the way students obtained financial aid.\",\"paragraph_3\":\"It amended the Higher Education Act of 1965 and reauthorized components of it. It also\\n                            created changes for schools that had to help prospective students and consumers understand\\n                            the net price of their education.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(53,19,'banner','{\"label\":\"Webinars\",\"title\":\"Sign Up to Stay Informed for Upcoming Webinars\",\"button_text\":\"Sign Up\",\"button_route\":\"get-started\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:50'),(54,19,'main','{\"title\":\"Access our previous Webinar Recorded Sessions here!\",\"button_text\":\"WATCH WEBINAR\",\"paragraph_1\":\"We are both dependable and responsive to our school partners, with the mutual\\n                    goal\\nof enhancing the overall student experience.\",\"paragraph_2\":\"This session is your gateway to mastering the art of unified strategies in enrollment\\n                            management.\",\"paragraph_3\":\"In this session, we will dive into the challenges related to HCM2 compliance, audit issues or\\n                            financial responsibility concerns.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(55,20,'banner','{\"label\":\"Resources\",\"title\":\"Stay Compliant, Stay Updated!\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(56,20,'checklist','{\"title\":\"December 2024\",\"button_text\":\"Download Your Checklist\",\"paragraph_1\":\"Are you ready to simplify complex regulations and stay ahead of essential deadlines? Download\\n                            our Financial Aid Regulatory and Compliance Checklist today and make\\n                            compliance easier for your team!\",\"paragraph_2\":\"Our Financial Aid Regulatory and Compliance Checklist is here to make it easier for you! This\\n                            comprehensive guide simplifies complex regulations, helping higher education professionals\\n                            stay on top of essential deadlines and tasks.\",\"paragraph_3\":\"Key Deadlines: Never miss a critical date\\nMust-Do Tasks: Ensure your institution remains compliant\\nFAFSA Updates: Stay informed on the latest changes\\nVerification Requirements: Get clear on what\\u2019s needed\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(57,21,'banner','{\"label\":\"FA Careers\",\"title\":\"Careers\"}',0,1,'2026-09-20 10:26:24','2026-09-20 10:26:24'),(58,21,'culture','{\"title\":\"Company Culture\",\"paragraph_1\":\"At FA Solutions, we believe that the well-being of our employees and delivering excellent and\\n                            personalized customer service go hand-in-hand to ensure that our business and clients are\\n                            successful. This is why we value work-life balance and delivering personalized and\\n                            exceptional customer service.\",\"paragraph_2\":\"Some people say, \\u201cYou can\\u2019t mix business with pleasure.\\u201d We say, \\u201cwhy not?\\u201d. Not only do we\\n                            make sure that the employees we hire fit our culture, but we also do our best to make sure\\n                            that the schools we partner with are comfortable with this culture as well. In short, when\\n                            you get to personally select the employees that work with you and the school partners that\\n                            you serve, then by all means, business is naturally mixed with pleasure.\"}',1,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(59,21,'who','{\"title\":\"Who We Are\",\"button_text\":\"View All Services\",\"paragraph_1\":\"Customer satisfaction and an enjoyable work environment are our most important goals.\",\"paragraph_2\":\"We are obsessed with having open and timely communication with our staff, and our school\\n                                partners. It makes for the best relationships.\\nWe don\\u2019t just work hard. We work smart \\u2013 meaning that we are effective and efficient\\n                                with how we work.\\nWe have a high level of respect for each other and our clients.\\nEach member of our team takes great pride in \\u201cgetting the job done\\u201d and in the quality\\n                                of the work that they each produce individually and as part of a team.\\nWe value and respect each other\\u2019s ideas.\\nWe are always looking for new and better ways of doing things.\\nWe appreciate a sense of humor.\",\"paragraph_3\":\"Customer satisfaction and an enjoyable work environment are our most important goals.\"}',2,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(60,21,'growth','{\"title\":\"Professional growth\",\"paragraph_1\":\"At FA Solutions, you can broaden your scope of knowledge, deepen your expertise, and\\n                                    develop your leadership skills.\\nWe encourage internal movement, strive to promote from within and continuously\\n                                    prepare you for the next exciting challenge of your career.\",\"paragraph_2\":\"At FA Solutions, you can broaden your scope of knowledge, deepen your expertise, and\\n                                    develop your leadership skills.\\nWe encourage internal movement, strive to promote from within and continuously\\n                                    prepare you for the next exciting challenge of your career.\",\"paragraph_3\":\"Some of our positions offer a flexible schedule so that people can build their work\\n                                    around their life, not the other way around. Although Florida sure is a great place\\n                                    to live, we offer opportunities in many cities and states throughout the country.\"}',3,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(61,21,'jobs','{\"title\":\"Current Job Openings\",\"button_text\":\"Apply Now\",\"paragraph_1\":\"Below are our current job openings. If FA Solutions sounds like it could be a fit for you, select\\n                    your desired position from the list below and click on the link to apply. We look forward to hearing\\n                    from you.\",\"paragraph_2\":\"No job openings match your search.\"}',4,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(62,21,'eeo','{\"paragraph_1\":\"FA Solutions provides equal employment opportunities (EEO) to all employees and applicants for\\n                        employment without regard to race, color, religion, sex, national origin, age, disability or\\n                        genetics. In addition to federal law requirements, FA Solutions complies with applicable state\\n                        and local laws governing nondiscrimination in employment in every location in which the company\\n                        has facilities. This policy applies to all terms and conditions of employment, including\\n                        recruiting, hiring, placement, promotion, termination, layoff, recall, transfer, leaves of\\n                        absence, compensation and training.\",\"paragraph_2\":\"FA Solutions expressly prohibits any form of workplace harassment based on race, color, religion,\\n                        gender, sexual orientation, gender identity or expression, national origin, age, genetic\\n                        information, disability, or veteran status. Improper interference with the ability of FA\\n                        Solutions\\u2019 employees to perform their job duties may result in discipline up to and including\\n                        discharge.\"}',5,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(63,21,'faq','{\"title\":\"Frequently Asked Questions\",\"items\":[{\"question\":\"Can you provide services on-site or remote?\",\"answer\":\"Yes. We are available for both on-site and remote assistance on a short or long-term\\n                                    basis. When FA Solutions was first established one of our goals was to offer\\n                                    complete redundancy of coverage in the event of a natural disaster. To do this, we\\n                                    invested heavily in cloud based technology to allow for remote staffing, while also\\n                                    allowing our employees to travel to unaffected areas so that work could be performed\\n                                    and service to students could continue with limited, or no interruption.\"},{\"question\":\"Is FA Solutions competitive with pricing compared to competitors?\",\"answer\":\"Absolutely. Everyone deserves the right to be cost-sensitive and receive good value\\n                                    for resources spent, and we keep this in mind as we customize our servicing\\n                                    solutions to fit the needs of each school that we work with. FA Solutions\\u2019 goal is\\n                                    to provide high level, quality services that add value to your institution.\"},{\"question\":\"What are your onboarding timelines?\",\"answer\":\"Most services can be onboarded within 15 to 30 business days and some as little as 10\\n                                    depending upon the services needed.\"},{\"question\":\"What levels of financial aid staffing do you provide?\",\"answer\":\"FA Solutions provides interim staffing from counselor to director level during busy\\n                                    processing and enrollment periods, for replacement staffing, and to fill vacancies\\n                                    resulting from staff turnover or medical or maternity leaves. Remote staffing saves\\n                                    institutions a significant amount of financial resources, and on-site interim\\n                                    staffing solutions are also available.\"},{\"question\":\"Do you provide a verification service?\",\"answer\":\"Yes. FA Solutions offers a customizable remote verification service that follows all\\n                                    Department of Education policies and procedures and ensures that the school\\u2019s\\n                                    methods, policies and procedures align with federal regulations.\"},{\"question\":\"Can you do a compliance audit?\",\"answer\":\"Yes. FA Solutions offers a comprehensive Financial Aid Department Regulatory and\\n                                    Operational Assessment. This proactive evaluation identifies potential regulatory\\n                                    liabilities and the cause(s) of processing inefficiencies.\"}]}',6,1,'2026-09-20 10:26:24','2026-09-20 11:23:43'),(64,19,'sessions','{\"items\":[{\"slug\":\"shattering-enrollment-silos--developing-unified-strategies\",\"title\":\"Rupak\",\"summary\":\"This session is your gateway to mastering the art of unified strategies in enrollment management.\",\"image\":\"images\\/webinar\\/shattering.jpg\",\"video_url\":null},{\"slug\":\"successful-strategies-to-manage-hcm2\",\"title\":\"Successful Strategies to Manage HCM2\",\"summary\":\"In this session, we will dive into the challenges related to HCM2 compliance, audit issues or financial responsibility concerns.\",\"image\":\"images\\/webinar\\/hcm2.jpg\",\"video_url\":\"https:\\/\\/youtu.be\\/NQ_hUHrFfx8\"},{\"slug\":\"2023-2024-fafsa-simplification-including-professional-judgements-and-cost-of-attendance-changes\",\"title\":\"2023-2024 FAFSA Simplification Including Professional Judgements and Cost of Attendance Changes\",\"summary\":\"The session will include an overview of the new FAFSA simplification requirements and how it affects professional judgements, cost of attendance, student eligibility and other changes.\",\"image\":\"images\\/webinar\\/fafsa-2023.jpg\",\"video_url\":null},{\"slug\":\"fafsa-simplification--spotlighting-sai-and-the-new-pell-calculation\",\"title\":\"FAFSA Simplification: Spotlighting SAI and the New Pell Calculation\",\"summary\":\"Gain a better understanding of the upcoming FAFSA Simplification Act change and it\\u2019s impact on the financial aid process. You will receive a basic understanding on the new Pell Grant calculation process and the SAI.\",\"image\":\"images\\/webinar\\/sai-pell.jpg\",\"video_url\":null},{\"slug\":\"latest-and-greatest-fafsa-simplification-information-and-impact-to-your-fa-office\",\"title\":\"Latest and Greatest FAFSA Simplification Information and Impact to your FA Office\",\"summary\":\"This session delves deeper into the FAFSA Simplification Act\'s implications, particularly emphasizing its impact on FA Offices.\",\"image\":\"images\\/webinar\\/latest-fafsa.jpg\",\"video_url\":null},{\"slug\":\"super-charge-student-experience-through-extraordinary-communication-strategies\",\"title\":\"Super Charge Student Experience through Extraordinary Communication Strategies\",\"summary\":\"Dive into the critical role of phone calls and emails in fostering meaningful connections with students. From initial inquiries to ongoing support, we\'ll explore strategies to maximize the effectiveness of these communication channels in keeping students engaged and satisfied.\",\"image\":\"images\\/webinar\\/communication.jpg\",\"video_url\":null},{\"slug\":\"skills-financial-aid-employees-need-in-the-21st-century\",\"title\":\"Skills Financial Aid Employees need in the 21st Century\",\"summary\":\"Given the broad arms of financial aid regulations, the need for a sufficiently sized, well-trained financial aid office staff is evident. Join the Exclusive Panel Discussion to learn more about the skills you need to assess while hiring Financial Aid Staff.\",\"image\":\"images\\/webinar\\/skills.jpg\",\"video_url\":null},{\"slug\":\"creating-an-efficient-financial-aid-office-by-eliminating-unnecessary-processes\",\"title\":\"Creating an Efficient Financial Aid office by Eliminating Unnecessary Processes\",\"summary\":\"Exclusive panel discussion with Amanda McCaughan, Director of Financial Aid, Concordia University \\u2013 St. Paul, Rita Franco, Financial Aid Director, Humphreys University, Nancy Rodriguez, Chief Executive Officer, BeOnAir Network of Media Schools, Bridget McGuire, VP of Operations, FA Solutions LLC and Rachel Gordon, Chief Operating Officer, Educational Compliance Management Inc.\",\"image\":\"images\\/webinar\\/efficient.png\",\"video_url\":null},{\"slug\":\"best-practices-on-consumer-information--policies-and-procedures\",\"title\":\"Best Practices on Consumer Information, Policies and Procedures\",\"summary\":\"In this one-hour Webinar; Deana Coady, Vice President, Federal Policy and Reporting, University of Phoenix, Jeremy Burciaga, Vice President, Academic Dean, Southwest University at El Paso, Kimberly Warren, Title IV Regulatory Specialist, Educational Compliance Management Inc., Bridget McGuire, VP of Operations, FA Solutions LLC and Rachel Gordon, Chief Operating Officer, Educational Compliance Management Inc.; will throw light on financial aid trends and strategies for monitoring compliance.\",\"image\":\"images\\/webinar\\/consumer.png\",\"video_url\":null},{\"slug\":\"breaking-down-silos-to-create-a-successful-enrollment-strategy\",\"title\":\"Breaking Down Silos to Create a Successful Enrollment Strategy\",\"summary\":\"In this one hour webinar, Financial Aid and Enrollment Management Department Professionals will get an overview of how they are unifying the goals with financial aid department to create a Successful Enrollment Management Strategy.\",\"image\":\"images\\/webinar\\/enrollment.png\",\"video_url\":null},{\"slug\":\"professional-judgments--a-way-to-compliance-and-student-success\",\"title\":\"Professional Judgments- A way to Compliance and Student Success\",\"summary\":\"Learn from the industry experts on how are they are following guidelines to Professional Judgement and making Financial Aid easier.\",\"image\":\"images\\/webinar\\/professional.jpg\",\"video_url\":null},{\"slug\":\"spotlight-covid-and-the-2-year-institutions--thriving-in-a-pandemic\",\"title\":\"Spotlight Covid and the 2 year institutions, thriving in a pandemic\",\"summary\":\"Exclusive panel discussion to throw a spotlight on #Covid and #2yearinstitutions, thriving in pandemic. Event will be MC\\u2019d by Pamela Notemyer Rogers.\",\"image\":\"images\\/webinar\\/covid.png\",\"video_url\":null},{\"slug\":\"highered-leadership-transition-from-covid-to-campus\",\"title\":\"HigherEd Leadership Transition from Covid to Campus\",\"summary\":\"Learn from the industry experts on how are they are getting ready to transform this crisis into a renewing wave.\",\"image\":\"images\\/webinar\\/leadership.png\",\"video_url\":null}]}',2,1,'2026-09-22 10:21:28','2026-09-22 11:26:05');
