INSERT INTO `page_seo` VALUES (1,'home','New Fa Solutions','FA Solutions partners with colleges to strengthen financial aid operations, ensure compliance, and deliver exceptional student support.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(2,'who-we-are','About FA Solutions | Financial Aid Experts','Learn about FA Solutions ΓÇö experienced financial aid professionals partnering with institutions to improve efficiency, compliance, and student outcomes.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(3,'team','Financial Aid Leadership Team | FA Solutions','Meet the FA Solutions leadership team ΓÇö seasoned financial aid experts dedicated to supporting institutions and students.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(4,'team.member','{member_name} | Leadership Team | FA Solutions','Learn more about {member_name} on the FA Solutions leadership team.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(5,'our-partnership','Higher Education Partnerships | FA Solutions','Discover how FA Solutions partners with colleges and universities to deliver reliable financial aid services and long-term operational support.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(6,'get-started','Get Started with FA Solutions | Financial Aid Support','Contact FA Solutions to discuss financial aid processing, staffing, outreach, and consulting services for your institution.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(7,'financial-aid-processing','Financial Aid Processing Services | FA Solutions','Outsource financial aid processing with FA Solutions ΓÇö compliance-focused support that integrates with your existing systems.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(8,'financial-aid-staffing','Financial Aid Staffing Solutions | FA Solutions','Scale your financial aid office with dependable W2 staffing, redundancy, and long-term team support from FA Solutions.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(9,'student-outreach-communication','Student Outreach & Communication | FA Solutions','Improve student engagement with FA Solutions contact center services, outreach programs, and two-way communication tools.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(10,'financial-aid-consulting','Financial Aid Consulting & Strategy | FA Solutions','Reduce compliance risk with financial aid consulting, operational assessments, and regulatory guidance from FA Solutions.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(11,'testimonials','Financial Aid Client Testimonials | FA Solutions','Read testimonials from institutions that partner with FA Solutions for financial aid processing, staffing, and compliance support.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(12,'case-studies','Financial Aid Case Studies | FA Solutions','Explore case studies showing how FA Solutions helps schools improve financial aid efficiency, compliance, and student experience.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(13,'blogs','Higher Education Financial Aid Blog | FA Solutions','Financial aid insights, compliance updates, and best practices from the FA Solutions team.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(14,'fed-updates','Federal Financial Aid Updates | FA Solutions','Stay current on federal financial aid policy changes, regulatory updates, and compliance news from FA Solutions.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(15,'knowledge-nuggets','FAFSA Simplification Resources | FA Solutions','Quick financial aid resources and knowledge nuggets to help your team navigate FAFSA and compliance changes.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(16,'white-paper-report','Financial Aid Compliance White Papers | FA Solutions','Download financial aid white papers and compliance reports from FA Solutions.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(17,'webinar','Higher Education Financial Aid Webinars | FA Solutions','Register for FA Solutions webinars on financial aid compliance, operations, and industry best practices.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(18,'financial-aid-regulatory-and-compliance-checklist','Financial Aid Regulatory and Compliance Checklist | FA Solutions','Use the FA Solutions regulatory and compliance checklist to evaluate your financial aid operations and reduce audit risk.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19'),(19,'careers','Financial Aid Careers | FA Solutions','Explore financial aid career opportunities at FA Solutions and join a team of dedicated higher education professionals.',NULL,'index, follow',NULL,NULL,NULL,NULL,'website','summary_large_image',NULL,NULL,NULL,'2026-09-20 11:30:19','2026-09-20 11:30:19');
